#!/bin/bash
#
# Merge external W3C vocabulary files into a single bundle
#
# This script concatenates all external vocabulary Turtle files into
# merged-external.ttl for offline loading by OntologyService.
#
# Usage:
#   cd ontologies/external
#   ./merge-external.sh
#
# The output file (merged-external.ttl) should be committed to the repo.

set -e

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
cd "$SCRIPT_DIR"

OUTPUT="merged-external.ttl"
TEMP="merged-external.tmp"

echo "Merging external vocabularies..."

# Start with header
cat > "$TEMP" << 'EOF'
# =============================================================================
# Merged External Vocabularies Bundle
# =============================================================================
#
# This file contains bundled W3C vocabularies for offline loading.
# Generated by: ontologies/external/merge-external.sh
#
# Contents:
#   - prov-o.ttl    : W3C PROV-O (Provenance Ontology)
#   - org.ttl       : W3C ORG (Organization Ontology)
#   - owl-time.ttl  : OWL-Time (Time Ontology)
#   - skos.ttl      : SKOS (Simple Knowledge Organization System)
#   - foaf.ttl      : FOAF (Friend of a Friend)
#   - web-annotation.ttl : W3C Web Annotation Ontology
#   - dcterms.ttl   : Dublin Core Terms
#
# DO NOT EDIT - regenerate using ./merge-external.sh
# =============================================================================

EOF

# Append each vocabulary file (in order of dependency)
for file in prov-o.ttl org.ttl owl-time.ttl skos.ttl foaf.ttl web-annotation.ttl dcterms.ttl; do
  if [ -f "$file" ]; then
    echo "  Adding $file..."
    echo "" >> "$TEMP"
    echo "# =============================================================================" >> "$TEMP"
    echo "# $file" >> "$TEMP"
    echo "# =============================================================================" >> "$TEMP"
    echo "" >> "$TEMP"
    cat "$file" >> "$TEMP"
  else
    echo "  WARNING: $file not found, skipping"
  fi
done

# Move to final location
mv "$TEMP" "$OUTPUT"

# Report
LINES=$(wc -l < "$OUTPUT" | tr -d ' ')
echo ""
echo "Created $OUTPUT ($LINES lines)"
echo "Done!"
